            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        xroot = find(x)
        yroot = find(y)
        if xroot == yroot:
            return False
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1
        return True
    mst_weight = 0
    mst_edges = []
    for w, u, v in edges:
